SELECT CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END AS rating_bucket, COUNT(DISTINCT rating) AS unique_countrys, SUM(CASE WHEN country = 'JP' THEN 1 ELSE 0 END) AS jp_count FROM suppliers WHERE country IN ('SG', 'JP') AND city NOT IN ('New York', 'London') GROUP BY CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 1.9 THEN 'mid' ELSE 'low' END;
